let ps;

function setup() {
	createCanvas(600, 600);
	ps = []
	for (let i = 0; i < 25; i++) {
		const x = random(width)
		const y = random(height)
		const dx = random(-2, 2)
		const dy = random(-2, 2)
		const c = color(random(333), random(111), random(222))
		const t = random("⬡⬢⬣".split(''))
		ps.push({x, y, dx, dy, t, c})
	}

	textAlign(CENTER, CENTER)
	textSize(width * 0.1)

	background(0, 0, 12)
}

function draw() {
	background(0, 0, 12)
	for (let p of ps) {
		p.x += p.dx;
		p.y += p.dy;
		stroke(p.c);
		text(p.t, p.x, p.y)


		if (random()<0.1) {
			p.dx = random(-2, 2)
			p.dy = random(-2, 2)
		}
	}
}
